-- Generated by Supabase CLI and moved into the sole canonical migration chain.
-- Postcard uploads keep their existing post_media source and media_assets owner.
BEGIN;

CREATE FUNCTION public.guard_postcard_canonical_asset()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $fn$
DECLARE source public.post_media%ROWTYPE; postcard_path constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[a-z0-9]+$';
BEGIN
  -- Postcard reservations use owner/post/media.ext. Other transports have
  -- their own lifecycle guard; a missing postcard source must never bypass it.
  IF TG_OP='UPDATE' AND
     (NEW.storage_bucket,NEW.storage_path,NEW.owner_user_id) IS DISTINCT FROM
     (OLD.storage_bucket,OLD.storage_path,OLD.owner_user_id) AND
     ((OLD.storage_bucket='post-media' AND OLD.storage_path ~* postcard_path) OR
      (NEW.storage_bucket='post-media' AND NEW.storage_path ~* postcard_path)) THEN
    RAISE EXCEPTION 'postcard_asset_identity_immutable';
  END IF;
  IF NEW.storage_bucket<>'post-media' OR NEW.storage_path !~* postcard_path THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' THEN
    IF NEW.deleted_at IS NOT NULL AND NEW.processing_status='removed'
       AND NEW.moderation_status IN ('owner_deleted','removed') AND
       (NEW.storage_bucket,NEW.storage_path,NEW.owner_user_id) IS NOT DISTINCT FROM
       (OLD.storage_bucket,OLD.storage_path,OLD.owner_user_id) THEN RETURN NEW; END IF;
    IF OLD.deleted_at IS NOT NULL OR OLD.moderation_status IN ('owner_deleted','removed') OR OLD.purge_status='completed' THEN
      RAISE EXCEPTION 'postcard_asset_retired';
    END IF;
    -- UPDATE already owns the asset row. Do not reverse source -> asset lock
    -- order: withdrawal will retire it after this update commits. Retired rows
    -- cannot be revived by a queued update after that retirement.
    SELECT * INTO source FROM public.post_media WHERE id=split_part(split_part(NEW.storage_path,'/',3),'.',1)::uuid
      AND post_id=split_part(NEW.storage_path,'/',2)::uuid AND storage_bucket=NEW.storage_bucket
      AND storage_path=NEW.storage_path AND user_id=NEW.owner_user_id;
  ELSE
    IF current_setting('transaction_isolation') NOT IN ('read committed','read uncommitted') THEN
      RAISE EXCEPTION 'postcard_lifecycle_requires_read_committed';
    END IF;
    -- SHARE conflicts with source deletion/update, but not another completion.
    -- Do not lock the parent: cancellation holds the parent and then this slot.
    SELECT * INTO source FROM public.post_media WHERE id=split_part(split_part(NEW.storage_path,'/',3),'.',1)::uuid
      AND post_id=split_part(NEW.storage_path,'/',2)::uuid AND storage_bucket=NEW.storage_bucket
      AND storage_path=NEW.storage_path AND user_id=NEW.owner_user_id FOR SHARE;
  END IF;
  IF source.id IS NULL OR lower(split_part(NEW.storage_path,'/',1))<>NEW.owner_user_id::text OR (source.processing_status<>'ready' AND NOT (source.processing_status='pending' AND NEW.processing_status='uploaded')) OR
     NOT EXISTS(SELECT 1 FROM public.posts p WHERE p.id=source.post_id
       AND p.author_id=NEW.owner_user_id AND p.status='active' AND p.deleted_at IS NULL
       AND p.postcard_draft_state IS DISTINCT FROM 'cancelled') OR
     NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.owner_user_id AND account_status='active') THEN
    RAISE EXCEPTION 'postcard_source_unavailable';
  END IF;
  RETURN NEW;
END;$fn$;
CREATE TRIGGER postcard_canonical_asset_guard BEFORE INSERT OR UPDATE ON public.media_assets
  FOR EACH ROW EXECUTE FUNCTION public.guard_postcard_canonical_asset();
REVOKE ALL ON FUNCTION public.guard_postcard_canonical_asset() FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.retire_postcard_media_source()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $fn$
DECLARE asset record;
BEGIN
  -- Composer/official assets may be shared by other posts. Only the uniquely
  -- allocated postcard reservation belongs to this source's lifecycle.
  IF OLD.storage_bucket<>'post-media' OR OLD.storage_path NOT ILIKE
     OLD.user_id::text||'/'||OLD.post_id::text||'/'||OLD.id::text||'.%' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' AND
     (NEW.storage_bucket,NEW.storage_path,NEW.user_id,NEW.post_id) IS NOT DISTINCT FROM
     (OLD.storage_bucket,OLD.storage_path,OLD.user_id,OLD.post_id) THEN RETURN NEW; END IF;
  IF current_setting('transaction_isolation') NOT IN ('read committed','read uncommitted') THEN
    RAISE EXCEPTION 'postcard_lifecycle_requires_read_committed';
  END IF;
  -- The source row is already exclusively locked. The lookup is a fresh
  -- statement after any insertion holding SHARE has committed.
  FOR asset IN SELECT id,owner_user_id FROM public.media_assets
    WHERE storage_bucket=OLD.storage_bucket AND storage_path=OLD.storage_path
      AND owner_user_id=OLD.user_id ORDER BY id LOOP
    PERFORM public.retire_media_asset(asset.id,asset.owner_user_id);
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;$fn$;
CREATE TRIGGER postcard_media_source_retired AFTER DELETE OR UPDATE OF storage_bucket,storage_path,user_id,post_id
  ON public.post_media FOR EACH ROW EXECUTE FUNCTION public.retire_postcard_media_source();
REVOKE ALL ON FUNCTION public.retire_postcard_media_source() FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.retire_withdrawn_postcard_assets()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $fn$
DECLARE source record; asset record;
BEGIN
  IF NEW.status='active' AND NEW.deleted_at IS NULL AND
     NEW.postcard_draft_state IS DISTINCT FROM 'cancelled' THEN RETURN NEW; END IF;
  IF current_setting('transaction_isolation') NOT IN ('read committed','read uncommitted') THEN
    RAISE EXCEPTION 'postcard_lifecycle_requires_read_committed';
  END IF;
  -- Source -> asset, including canonical inserts that started before the parent
  -- withdrawal. A new insert waiting here rechecks the withdrawn parent.
  FOR source IN SELECT storage_bucket,storage_path,user_id FROM public.post_media
    WHERE post_id=NEW.id AND storage_bucket='post-media'
      AND storage_path ILIKE user_id::text||'/'||post_id::text||'/'||id::text||'.%'
    ORDER BY id FOR UPDATE LOOP
    FOR asset IN SELECT id,owner_user_id FROM public.media_assets
      WHERE storage_bucket=source.storage_bucket AND storage_path=source.storage_path
        AND owner_user_id=source.user_id ORDER BY id LOOP
      PERFORM public.retire_media_asset(asset.id,asset.owner_user_id);
    END LOOP;
  END LOOP;
  RETURN NEW;
END;$fn$;
-- Cancellation first moves its upload slots to pending for the existing late-
-- PUT sweep. Retire at the same transaction's commit, after those updates, so
-- the existing terminal-publication guard never has to permit a retired asset
-- to be reattached. A failure here still rolls back the entire withdrawal.
CREATE CONSTRAINT TRIGGER postcard_assets_withdrawn AFTER UPDATE ON public.posts
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
  WHEN (NEW.status<>'active' OR NEW.deleted_at IS NOT NULL OR NEW.postcard_draft_state='cancelled')
  EXECUTE FUNCTION public.retire_withdrawn_postcard_assets();
REVOKE ALL ON FUNCTION public.retire_withdrawn_postcard_assets() FROM PUBLIC,anon,authenticated;
-- A committed cancellation is already a durable receipt. Do not replay its
-- pending-slot UPDATE after retirement: the terminal publication guard must
-- continue rejecting writes which could reattach a removed canonical asset.
DO $cancel_receipt$
DECLARE definition text;
  anchor text := '  IF NOT FOUND THEN RETURN jsonb_build_object(''ok'',true,''absent'',true); END IF;';
  receipt text := '  IF p.postcard_draft_state=''cancelled'' THEN RETURN jsonb_build_object(''ok'',true,''absent'',false); END IF;';
BEGIN
  definition := pg_get_functiondef('public.cancel_postcard_draft(uuid,uuid)'::regprocedure);
  IF position(receipt IN definition)=0 THEN
    IF (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 THEN
      RAISE EXCEPTION '4038 cancellation receipt anchor changed: review before applying';
    END IF;
    EXECUTE replace(definition,anchor,anchor || E'\n' || receipt);
  END IF;
END;$cancel_receipt$;
-- Reconcile pre-guard orphaned postcard receipts through the same retirement
-- owner. Shared composer/official keys and live sources are deliberately kept.
-- Rollout must preview this predicate on the verified target before applying.
DO $reconcile_postcard_assets$
DECLARE asset record;
BEGIN
  FOR asset IN SELECT a.id,a.owner_user_id FROM public.media_assets a
    WHERE a.storage_bucket='post-media' AND a.storage_path ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[a-z0-9]+$'
      AND a.deleted_at IS NULL AND a.moderation_status<>'owner_deleted' AND a.purge_status<>'completed'
      AND NOT EXISTS(SELECT 1 FROM public.post_media s JOIN public.posts p ON p.id=s.post_id
        WHERE s.storage_bucket=a.storage_bucket AND s.storage_path=a.storage_path
          AND s.user_id=a.owner_user_id AND p.author_id=a.owner_user_id
          AND a.storage_path ILIKE s.user_id::text||'/'||s.post_id::text||'/'||s.id::text||'.%'
          AND p.status='active' AND p.deleted_at IS NULL AND p.postcard_draft_state IS DISTINCT FROM 'cancelled')
    ORDER BY a.id LOOP
    PERFORM public.retire_media_asset(asset.id,asset.owner_user_id);
  END LOOP;
END;$reconcile_postcard_assets$;
-- Read-only capability receipt for the complete path. Capture must be durable
-- before EXIF stripping, and an uploaded asset must not be distributed yet.
-- Fingerprints freeze the installed definitions; a later partial rollback or
-- disabled/replaced guard fails readiness instead of trusting migration history.
DO $readiness$
DECLARE definitions text; trigger_definitions text;
BEGIN
  PERFORM set_config('search_path','pg_catalog,pg_temp',true);
  SELECT string_agg(format('(%L,%L)',name,md5(pg_get_functiondef(to_regprocedure(name)))),',') INTO definitions
    FROM (VALUES('public.guard_postcard_canonical_asset()'),('public.retire_postcard_media_source()'),
      ('public.retire_withdrawn_postcard_assets()'),('public.retire_media_asset(uuid,uuid)'),
      ('public.cancel_postcard_draft(uuid,uuid)')) functions(name);
  SELECT string_agg(format('(%L::regclass,%L,%L)',t.tgrelid::regclass::text,t.tgname,md5(pg_get_triggerdef(t.oid))),',') INTO trigger_definitions
    FROM pg_trigger t JOIN (VALUES ('public.media_assets'::regclass,'postcard_canonical_asset_guard'),
      ('public.post_media'::regclass,'postcard_media_source_retired'),('public.posts'::regclass,'postcard_assets_withdrawn')) expected(relation,name)
      ON t.tgrelid=expected.relation AND t.tgname=expected.name;
  EXECUTE format($definition$
    CREATE FUNCTION public.postcard_canonical_lifecycle_ready()
    RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $probe$
      SELECT NOT EXISTS(SELECT 1 FROM (VALUES %s) expected(name,fingerprint)
        WHERE to_regprocedure(name) IS NULL OR md5(pg_get_functiondef(to_regprocedure(name))) IS DISTINCT FROM fingerprint)
      AND (SELECT count(*)=3 FROM pg_trigger t JOIN (VALUES %s) expected(relation,name,fingerprint)
        ON t.tgrelid=expected.relation AND t.tgname=expected.name
        WHERE t.tgenabled IN ('O','A') AND md5(pg_get_triggerdef(t.oid))=expected.fingerprint);
    $probe$;
  $definition$,definitions,trigger_definitions);
END;$readiness$;
REVOKE ALL ON FUNCTION public.postcard_canonical_lifecycle_ready() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.postcard_canonical_lifecycle_ready() TO service_role;
COMMIT;
